// RAII via Standard Library (Strong Exception Guarantee)
std::unique_ptr<FileHandle> file(
    open_file("data.txt"));

// Custom RAII Wrapper: Basic Guarantee
class LockGuard {
    Mutex& m;
public:
    explicit LockGuard(Mutex& mx) : m(mx) { m.lock(); }
    ~LockGuard() { m.unlock(); } // Must not throw
};

// Destructor Exception Safety Rule
// C++11 onwards: Implicitly noexcept(true) if no exceptions thrown
class SafeResource {
    Handle h;
public:
    ~SafeResource() noexcept {
        release(h); // Ensure no exceptions escape
    }
};
